head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.gUpDepCd = js_belngdepcd;
scwin.key_seq = '';
scwin.vScrenID = "ULDSTF30410.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.initPage = function() {
    // 1. 날짜 기본 6개월.
    var ToDay = $c.ut.cGetToday2();
    $c.stf.setObjectValue(edt_EDATE, ToDay);
    var vSDATE = $c.ut.calcMonth(ToDay, -3);
    $c.stf.setObjectValue(edt_SDATE, vSDATE);
    $c.stf.setObjectValue(rdo_MKT_ID, scwin.gLdMktTp);
    if (scwin.gLdMktTp != '9') {
        $c.stf.showObj(panel_mkt, false);
    }

    /**
    dts_DECLR_TP.DataID = "/CodeAction.do?method=listCodeValueName&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT"+
    						"&FOR=R&CD_ID=02571&CD_ENG_NM=DECLR_TP_CD" ;
    dts_DECLR_TP.Reset();
    **/
    /*
    <!--<column id="DEP_NM" width="100" name="담당팀" value="{DECODE(DEL_DEP_CD, 'YYYY', DEP_NM, DEL_DEP_NM)}" sort="true" edit="none" headcolor="#ffffff" headbgcolor="#598fd5"></column>
    					<column id="EMP_NM" width="100" name="담당자" sort="true" edit="none" headcolor="#ffffff" headbgcolor="#598fd5"></column>-->
    */
    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)	
    dts_dep.DataID = "/CodeAction.do?method=getDepUpCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_dep.Reset();


    //담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)	
    dts_emp.DataID = "/CodeAction.do?method=getEmpNoDepCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_emp.Reset();


    //포상대상년도 항목의 콤보박스 값 설정(2011년 ~ 현재년도+1)
    var ToDay = new Date();
    var yyyy = parseInt(ToDay.getYear(), 10);
    yyyy = yyyy + 1;
    var str = "2011:2011년";
    for (var i = 2012; i <= yyyy; i++) {
        str += "," + i + ":" + i + "년";
    }
    str += ",-1:미해당";
    $c.cm.setColumnProp(grd_Grid, "RWD_OBJ_YY", 'data', str);
    //data="2011:2011년,2012:2012년,-1:미해당" 

};
scwin.fn_Search = function() {
    if (scwin.gDepCd == "UPTEAM" && js_dep_cd.substr(2, 4) == '00') {
        //부서장 처리
        scwin.gUpDepCd = js_dep_cd;
    }
    $c.cm.ShowWin(grd_Grid);
    var url = "/UnfaithfulDesignReport.do?method=listNfaithDsclDecl";
    url += "&ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd);
    url += "&DECL_CORP_NFAITHDISCLS_TP_CD=" + $c.stf.getObjectValue(cmb_DECL_CORP_NFAITHDISCLS_TP_CD); //불성실공시 유형분코드
    url += "&DECLR_TP_CD=" + $c.stf.getObjectValue(cmb_DECLR_TP_CD);
    url += "&DECLR_NM=" + $c.stf.getObjectValue(txb_DECLR_NM);
    url += "&SDATE=" + $c.stf.getObjectValue(edt_SDATE);
    url += "&EDATE=" + $c.stf.getObjectValue(edt_EDATE);
    url += "&EMP_NO=" + $c.stf.getObjectValue(cmb_EmpList); //담당자
    url += "&DEP_CD=" + $c.stf.getObjectValue(cmb_TeamList); //팀(부서코드)
    url += "&UP_DEP_CD=" + scwin.gUpDepCd; //상위부서코드
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&LD_MKT_TP_CD=" + $c.stf.getObjectValue(rdo_MKT_ID); //불성실공시 시장구분코드
    url += "&ME_EMP_NO=" + js_emp_no; //로그인한사용자ID
    url += "&ME_DEP_CD=" + js_dep_cd; //로그인한사용자 팀코드
    url += "&ME_JOBTITL=" + js_jobtitl; //로그인한사용자 직책

    //alert(url);
    dts_Grid.DataID = encodeURI(url);
    dts_Grid.Reset();
};
scwin.fn_readDecl = async function(seq) {
    await $c.frame.CreateDialogFrame("ULDSTF30407", "/dsclinfo/ULDSTF30411.gfm", "불성실공시신고포상상세화면", 50, 20, 785, 695, "window");
};
scwin.fn_Save = function() {
    var gCnt = 0;
    for (var k = 1; k <= dts_Grid.getTotalRow(); k++) {
        gStat = dts_Grid.getRowStatus(k);
        if (gStat == TB_JOB_UPDATE) {
            gCnt++;
        }
    }
    grd_Grid.Redraw = true;
    if (gCnt == 0) {
        $c.win.alert("저장할 내용이 없습니다.");
        return;
    }
    if (window.confirm("[총" + gCnt + "건] 저장하겠습니까?")) {
        var url = "/UnfaithfulDesignReport.do?method=procsNfaithDsclDecl&TRANSTR_EMP_NO=" + js_emp_no + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
        trs_save.Action = url;
        trs_save.KeyName = "toinb_dataid4";
        trs_save.KeyValue = "JSP(I:pInput=dts_Grid)";
        trs_save.Post();
    }
};
scwin.fn_setKey = function(seq) {
    scwin.key_seq = seq;
};
scwin.fn_checkNum = function(row, colid, data) {
    var num = dts_Grid.getCellData(row, colid);
    num = num.replace(/\,|\(|\)/g, '');
    num = num.replace(/\s/g, '');
    dts_Grid.setCellData(row, colid, num);
    if (isNaN(dts_Grid.getCellData(row, colid))) {
        $c.win.alert("올바른 숫자형식으로 값을 입력해주세요.");
        grd_Grid.focus();
    }
};
scwin.fn_checkDate = function(row, colid, data) {
    var num = dts_Grid.getCellData(row, colid);
    num = num.replace(/\.|\(|\)/g, '');
    num = num.replace(/\s/g, '');
    dts_Grid.setCellData(row, colid, num);
    if (num.length != 8 && num.length != 0) {
        $c.win.alert("올바른 날자를 입력해주세요.");
        grd_Grid.focus();
    }
};
scwin.fn_addDsclTeamAll = function(rowcount) {
    dts_dep.setCellData(2, "VALUE", 'UPTEAM');
    dts_dep.setCellData(2, "TEXT", '공시팀 전체');
    dts_dep.setCellData(2, "DEP_CD", 'UPTEAM');
    for (var i = 3; i <= rowcount; i++) {
        dts_dep.setCellData(i, "VALUE", dts_dep1.getCellData(i - 1, "VALUE"));
        dts_dep.setCellData(i, "TEXT", dts_dep1.getCellData(i - 1, "TEXT"));
        dts_dep.setCellData(i, "DEP_CD", dts_dep1.getCellData(i - 1, "DEP_CD"));
    }
    dts_dep.insertRow();
    dts_dep.setCellData(rowcount + 1, "VALUE", dts_dep1.getCellData(rowcount, "VALUE"));
    dts_dep.setCellData(rowcount + 1, "TEXT", dts_dep1.getCellData(rowcount, "TEXT"));
    dts_dep.setCellData(rowcount + 1, "DEP_CD", dts_dep1.getCellData(rowcount, "DEP_CD"));
};
scwin.btn_SDATE_onclick = function() {
    popUpCalendar2(edt_SDATE);
};
scwin.btn_EDATE_onclick = function() {
    popUpCalendar2(edt_EDATE);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.stf.getObjectValue(cmb_PeriodTp);
    $c.stf.fn_setFromToDate(vTp, edt_SDATE, edt_EDATE);
};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    //var vTotalCnt = dts_Grid.NameString(1, "CNT");	
    //alert("vTotalCnt=" + vTotalCnt);
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_Grid);
};
scwin.dts_Grid_OnLoadError = function() {
    $c.stf.alert_error(dts_Grid);
};
scwin.grd_Grid_OnDblClick = function(row, colid) {
    if (colid == "DECLR_NM") {
        //권한 추가 20240621		
        if (dts_Grid.getCellData(row, "CHECK_YN") == "Y") {
            scwin.fn_readDecl(dts_Grid.getCellData(row, "DECL_SEQ"));
        }
    }
};
scwin.grd_Grid_OnClick = function(row, colid) {
    scwin.fn_setKey(dts_Grid.getCellData(row, "DECL_SEQ"));
};
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() == "") {
        txb_COM_NM.setValue("");
    }
};
scwin.txb_isur_cd_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.btn_ISUR_CD_onclick = function() {
    $c.cm.IsurcdSearch(txb_isur_cd, txb_COM_NM);
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else return true;
};
scwin.btn_New_onclick = function() {
    scwin.key_seq = '';
    scwin.fn_readDecl();
};
scwin.btn_Modify_onclick = function() {
    scwin.fn_Save();
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_Grid, '불성실공시 신고포상현황', '', 8);
};
scwin.grd_Grid_OnCloseUp = function(row, colid) {
    if (colid == "RWD_PNT_CONV_YN") {
        if (dts_Grid.getCellData(row, colid) == "Y" && dts_Grid.getCellData(row, "DECL_CORP_IMPOST_PNLT") != "") {
            dts_Grid.setCellData(row, "DECLR_RWD_PNT", dts_Grid.getCellData(row, "DECL_CORP_IMPOST_PNLT"));
        } else {
            dts_Grid.setCellData(row, "DECLR_RWD_PNT", "미해당");
        }
    }
};
scwin.grd_Grid_OnExit = function(row, colid, olddata) {
    if ((colid == "DECL_CORP_IMPOST_PNLT" || colid == "DECLR_RWD_AMT" || colid == "DECLR_ANUL_RWD_AMT")) {
        scwin.fn_checkNum(row, colid, olddata);
    }
    if ((colid == "DECL_PROCS_END_DD" || colid == "DECL_CORP_NFAITH_ADVNOTI_DD" || colid == "DECL_CORP_NFAITH_DESIGN_DD" || colid == "DECLR_RWD_DD" || colid == "DECLR_ANUL_RWD_DD")) {
        scwin.fn_checkDate(row, colid, olddata);
    }
};
scwin.grd_Grid_CanColumnPosChange = function(row, colid) {
    value.setValue(dts_Grid.getCellData(row, colid));
    if (isNaN(value) && (colid == 'DECL_CORP_IMPOST_PNLT' || colid == 'DECLR_RWD_AMT' || colid == 'DECLR_ANUL_RWD_AMT')) {
        return false;
    } else if ((colid == 'DECL_PROCS_END_DD' || colid == 'DECL_CORP_NFAITH_ADVNOTI_DD' || colid == 'DECL_CORP_NFAITH_DESIGN_DD' || colid == 'DECLR_RWD_DD' || colid == 'DECLR_ANUL_RWD_DD') && !(value.length == 0 || value.length == 8)) {
        return false;
    } else {
        return true;
    }
};
scwin.cmb_TeamList_OnSelChange = function() {
    scwin.gDepCd = $c.cp.valueOfIndex(cmb_TeamList, "VALUE", cmb_TeamList.getSelectedIndex());
    if (scwin.gDepCd == '' || scwin.gDepCd == 'UPTEAM') {
        $c.stf.setObjectValue(cmb_EmpList, '');
    }
    dts_emp.UseFilter = true;
    dts_emp.Filter();
    dts_emp.sort("DEP_CD", 0);
    //dts_emp.sort(); // W-Craft 주석처리 
    if (scwin.gDepCd != '' && scwin.gDepCd != 'UPTEAM') {
        cmb_EmpList.trigger("onclick");
    }
};
scwin.dts_emp_OnFilter = function(row) {
    //  부서코드에  해당하는 사원을 가져온다.
    if (scwin.gDepCd == "" || scwin.gDepCd == "UPTEAM") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        if (dts_emp.getCellData(row, "dep_cd") == scwin.gDepCd ||
            dts_emp.getCellData(row, "dep_cd") == "UPTEAM" ||
            dts_emp.getCellData(row, "dep_cd") == "") {
            return true;
        } else {
            return false;
        }
    }
};
scwin.dts_dep_OnLoadCompleted = function(rowcount) {
    if (js_dep_cd.substring(0, 2) == '26' || js_dep_cd.substring(0, 2) == '34') {
        $c.stf.CopyDataSet(dts_dep, dts_dep1);
        scwin.fn_addDsclTeamAll(rowcount);
        $c.stf.setObjectValue(cmb_TeamList, 'UPTEAM');
    }
};
scwin.trs_save_OnSuccess = function() {
    scwin.fn_Search();
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    scwin.initPage();
    $c.cm.fn_com_isur(txb_isur_cd, txb_COM_NM);
    //fn_Search();

};
scwin.rdo_MKT_ID_OnSelChange = function() {
    //fn_SetCtrlByMktId();

};
